shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,76 @@
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set expected_slots {{0 5461} {5462 10922} {10923 16383}}
+
+    test "CLUSTER SHARDS reports slots for healthy shards" {
+        for {set j 0} {$j < 6} {incr j} {
+            set slots {}
+            foreach shard [R $j CLUSTER SHARDS] {
+                lappend slots [dict get $shard slots]
+                assert_equal 2 [llength [dict get $shard nodes]]
+            }
+            assert_equal [lsort $expected_slots] [lsort $slots]
+        }
+    }
+
+    set primary_id [R 0 CLUSTER MYID]
+    set replica_id [R 3 CLUSTER MYID]
+    set primary_pid [srv 0 pid]
+
+    test "CLUSTER SHARDS retains slots after a primary fails over" {
+        wait_for_sync [srv -3 client]
+        pause_process $primary_pid
+
+        wait_for_condition 1000 50 {
+            [s -3 role] eq "master"
+        } else {
+            fail "Replica did not take over the failed primary"
+        }
+
+        for {set j 1} {$j < 6} {incr j} {
+            wait_for_condition 1000 50 {
+                [CI $j cluster_state] eq "ok" &&
+                [dict get [cluster_get_node_by_id $j $replica_id] slots] eq "0-5461" &&
+                [dict get [cluster_get_node_by_id $j $primary_id] slots] eq {}
+            } else {
+                fail "Node $j did not learn the promoted primary's slots"
+            }
+
+            # The stopped primary still advertises itself as a primary.
+            assert {[cluster_has_flag [cluster_get_node_by_id $j $primary_id] master]}
+            for {set attempt 0} {$attempt < 2} {incr attempt} {
+                set slots {}
+                foreach shard [R $j CLUSTER SHARDS] {
+                    lappend slots [dict get $shard slots]
+                }
+                assert_equal [lsort $expected_slots] [lsort $slots]
+            }
+        }
+    }
+
+    resume_process $primary_pid
+    wait_for_cluster_propagation
+}
+
+start_cluster 1 0 {tags {external:skip cluster}} {
+    test "CLUSTER SHARDS reports discontinuous slot ranges" {
+        R 0 CLUSTER DELSLOTS 0 2 8192 16382 16383
+        set shards [R 0 CLUSTER SHARDS]
+        assert_equal 1 [llength $shards]
+        assert_equal {1 1 3 8191 8193 16381} [dict get [lindex $shards 0] slots]
+    }
+
+    test "CLUSTER SHARDS reports empty slots for a slotless shard" {
+        R 0 CLUSTER DELSLOTSRANGE 1 1 3 8191 8193 16381
+        set shards [R 0 CLUSTER SHARDS]
+        assert_equal 1 [llength $shards]
+        assert_equal {} [dict get [lindex $shards 0] slots]
+        assert_equal 1 [llength [dict get [lindex $shards 0] nodes]]
+    }
+}
PATCH
./runtest --single unit/cluster/cluster-shards

