cd /testbed && grep -nE 'listNextNode|for \(listNode \*.*listFirst' src/cluster_legacy.c src/adlist.h | head -30 && git apply --recount <<'PATCH'
diff --git a/src/cluster_legacy.c b/src/cluster_legacy.c
--- a/src/cluster_legacy.c
+++ b/src/cluster_legacy.c
@@ -5663,16 +5663,24 @@
-/* Add the shard reply of a single shard based off the given primary node. */
+/* Add the shard reply of a single shard based off the given list of nodes. */
 void addShardReplyForClusterShards(client *c, list *nodes) {
     serverAssert(listLength(nodes) > 0);
-    clusterNode *n = listNodeValue(listFirst(nodes));
+    clusterNode *n = NULL;
+    /* After failover, the old primary may still be listed first, but no longer
+     * owns any slots. Find the node that actually owns the shard's slots. */
+    for (listNode *ln = listFirst(nodes); ln != NULL; ln = listNextNode(ln)) {
+        clusterNode *node = listNodeValue(ln);
+        if (node->slot_info_pairs != NULL) {
+            n = node;
+            break;
+        }
+    }
+
     addReplyMapLen(c, 2);
     addReplyBulkCString(c, "slots");

-    /* Use slot_info_pairs from the primary only */
-    n = clusterNodeGetPrimary(n);
-
-    if (n->slot_info_pairs != NULL) {
+    if (n != NULL) {
         serverAssert((n->slot_info_pairs_count % 2) == 0);
         addReplyArrayLen(c, n->slot_info_pairs_count);
         for (int i = 0; i < n->slot_info_pairs_count; i++) addReplyLongLong(c, (unsigned long)n->slot_info_pairs[i]);
     } else {
-        /* If no slot info pair is provided, the node owns no slots */
+        /* If no node has slot info pairs, the shard owns no slots. */
         addReplyArrayLen(c, 0);
     }
PATCH
make -j4

